import{_ as o,a0 as n,w as p,s as d,ao as h,I as t,x as e,a1 as a,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"在 Linux 中移除從源代碼安裝的程序的一種簡單的方法 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 中移除從源代碼安裝的程序的一種簡單的方法 | LCTT (201901) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 中移除從源代碼安裝的程序的一種簡單的方法 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 中移除從源代碼安裝的程序的一種簡單的方法 | LCTT (201901) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201901/20181221 An Easy Way To Remove Programs Installed From Source In Linux","title":"在 Linux 中移除從源代碼安裝的程序的一種簡單的方法","tag":"201901","desc":""},"relativePath":"201901/20181221 An Easy Way To Remove Programs Installed From Source In Linux.md","filePath":"[post].md"}'),r={name:"201901/20181221 An Easy Way To Remove Programs Installed From Source In Linux.md"};function c(g,s,u,k,b,f){const i=n("Link");return p(),d("div",null,[s[15]||(s[15]=h(`<h1 id="在-linux-中移除從源代碼安裝的程序的一種簡單的方法" tabindex="-1">在 Linux 中移除從源代碼安裝的程序的一種簡單的方法 <a class="header-anchor" href="#在-linux-中移除從源代碼安裝的程序的一種簡單的方法" aria-label="Permalink to “在 Linux 中移除從源代碼安裝的程序的一種簡單的方法”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/12/stow-1-720x340.jpg" alt=""></p><p>不是所有的程序都可以在官方或者第三方庫中找到，因此你不能使用常規的包管理來安裝它們。有時你不得不從源代碼中手動構建這些程序。就如你已經知道的一樣，當你從源代碼中安裝一個程序的時候，這個軟件包所包含的文件將會複製到本地的多個位置，例如 <code>/usr/local/bin</code>、<code>/usr/local/etc/</code>。如果從源代碼中安裝的程序沒有內置的卸載程序，當你不再需要這個程序的時候，卸載它就會很麻煩。你可能會花費雙倍（甚至更多）的時間找出這些文件然後手動刪除它們。我以前一直是這樣做的，直到我發現了 GNU Stow。謝天謝地，Stow 有一個很棒的方法可以輕鬆管理從源代碼安裝的程序。</p><p>引用官方網站裏的一段介紹，</p><blockquote><p>GNU Stow 是一個符號鏈接歸集管理器，它可以收集文件系統上不同目錄中的不同軟件和/或數據包，使它們看起來像是一個整體。</p></blockquote><p>簡單來説，Stow 幫助你把這些程序文件以一種容易管理的方式組織在了一起。在這個方法中，文件將不會被複制到多個位置。所有的這些文件都會被保存在一個特定的文件夾中，通常是以程序名命名的，然後 Stow 會在一個合適的位置為所有的程序文件創建符號連接。比如 <code>/usr/local/bin</code> 中會包含 <code>/usr/local/stow/vim/bin</code>、<code>/usr/local/stow/python/bin</code> 中文件的符號鏈接。並且同樣遞歸地用於其他的任何的子目錄，例如 <code>.../share</code>、<code>.../man</code>，等等。在這篇教程中，我將會舉例教你如何輕鬆地使用 Stow 管理從源中安裝的程序。</p><h3 id="安裝-gnu-stow" tabindex="-1">安裝 GNU Stow <a class="header-anchor" href="#安裝-gnu-stow" aria-label="Permalink to “安裝 GNU Stow”">​</a></h3><p>GNU Stow 在流行 Linux 操作系統的默認庫中都可用。</p><p>在 Arch Linux 及它的衍生版本中，運行下面的命令安裝 Stow。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pacman -S stow</span></span></code></pre></div><p>在 Debian、Ubuntu、Linux Mint 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install stow</span></span></code></pre></div><p>在 Fedora 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install stow</span></span></code></pre></div><p>在 RHEL/CentOS 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo yum install epel-release</span></span>
<span class="line"><span>$ sudo yum install stow</span></span></code></pre></div><h3 id="在-linux-上輕鬆移除從源代碼安裝的程序" tabindex="-1">在 Linux 上輕鬆移除從源代碼安裝的程序 <a class="header-anchor" href="#在-linux-上輕鬆移除從源代碼安裝的程序" aria-label="Permalink to “在 Linux 上輕鬆移除從源代碼安裝的程序”">​</a></h3><p>就像我之前提到的，所有包的程序文件都將被保存在位於 <code>/usr/local/stow/</code> 的一個根文件夾。在這個根文件夾或者父目錄之下，每個包都將保存在對應的子目錄中。例如，如果我們從源代碼中安裝了 Vim 編輯器，所有關聯到 Vim 的程序文件和目錄都將保存在 <code>/usr/local/stow/vim</code> 文件夾之下。如果你從源代碼中安裝了 Python，所有關聯到 python 的文件都會保存在 <code>/usr/local/stow/python</code> 之下。</p><p>我現在從源代碼中來安裝一個叫做 hello 的程序。</p><p>首先下載 hello 程序的壓縮包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wget http://ftp.gnu.org/gnu/hello/hello-2.10.tar.gz</span></span></code></pre></div><p>使用下面的命令解壓壓縮包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tar -zxvf hello-2.10.tar.gz</span></span></code></pre></div><p>上面的命令將會在當前工作目錄下創建一個叫做 <code>hello-2.10</code> 的目錄，並且提取壓縮包中的所有內容到其中去。</p><p>切換到這個目錄當中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd hello-2.10/</span></span></code></pre></div><p>運行下面的命令，並且添加 <code>-prefix</code> 選項。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ./configure --prefix=/usr/local/stow/hello</span></span></code></pre></div><p>上面的命令將會保存構建文件到一個指定位置，在這個例子中是 <code>/usr/local/stow/hello</code>。</p><p>最後，使用下面的命令構建並安裝 hello 這個程序：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ make</span></span>
<span class="line"><span>$ sudo make install</span></span></code></pre></div><p>就這樣。hello 這個程序就已經安裝在 <code>/usr/local/stow/hello/</code> 這個位置了。你可以使用下面的 <code>ls</code> 命令確認一下。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls /usr/local/stow/hello/</span></span>
<span class="line"><span>bin share</span></span></code></pre></div><p>最後，進入 <code>/usr/local/stow/</code> 目錄，運行下面的命令來生成必要的符號鏈接。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd /usr/local/stow/</span></span>
<span class="line"><span>$ sudo stow hello</span></span></code></pre></div><p>大功告成！</p><p>剛才那一步是將包含在 hello 這個程序中的所有文件或者目錄創建了鏈接到 <code>/usr/local/</code> 目錄中。換一種説法， <code>/usr/local/stow/hello/bin</code> 鏈接到 <code>/usr/local/share</code>，以及 <code>/usr/local/stow/hello/share/man</code> 鏈接到 <code>/usr/local/share</code>，還有 <code>/usr/local/stow/hello/share/man</code> 鏈接到 <code>/usr/local/share/man</code>。</p><p>你可以使用 <code>ls</code> 命令來確認一下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls /usr/local/bin/</span></span>
<span class="line"><span>hello</span></span></code></pre></div><p>可以使用下面的命令來確認 hello 這個程序是否可以正常工作了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ hello</span></span>
<span class="line"><span>Hello, world!</span></span></code></pre></div><p>很好，它已經開始工作了！！</p><p>類似地，你可以像上面描述的那樣安裝程序到它對應的子目錄下。</p><p>下面是 Stow 根目錄包含的內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tree /usr/local/stow/</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/12/tree-command.png" alt=""></p><p>看，hello 這個程序已經安裝在 <code>/usr/local/stow/hello/</code> 下。同樣地，所有的包都將保存在它們對應的目錄之下。</p><p>下面進入主要環節，移除 hello 這個程序。首先進入 <code>/usr/local/stow/</code> 目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd /usr/local/stow/</span></span></code></pre></div><p>然後運行下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo stow --delete hello</span></span></code></pre></div><p>hello 這個程序就會被移除了。你可以使用下面的命令確認它是否真的被移除了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ hello</span></span>
<span class="line"><span>-bash: /usr/local/bin/hello: No such file or directory</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/12/hello-world.png" alt=""></p><p>看， Hello 已經被移除了！</p><p>請注意 Stow 僅僅只移除了符號鏈接。所有與 hello 這個程序相關的文件或者目錄還保存在 <code>/usr/local/stow/hello</code> 目錄下。所以你無需再次下載源文件就可以再次安裝 hello 這個程序。如果你不再需要它了，直接刪除這個文件夾即可。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo rm -fr /usr/local/stow/hello/</span></span></code></pre></div><p>想了解更多 Stow 的細節，請參閲 man 手冊。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man stow</span></span></code></pre></div><p>Stow 可以像安裝程序一樣輕鬆地幫你移除它。如果你想知道如何高效的管理很多從源代碼中安裝的程序，GNU Stow 就是一個使得這個任務更加輕鬆的一個選擇，嘗試一下，你一定不會失望的。</p><p>這就是所有的內容了，希望對你有所幫助。還有更多幹活即將到來，可以期待一下的！</p><p>祝近祺！</p><hr>`,63)),t("p",null,[s[1]||(s[1]=e("via: ",-1)),a(i,{href:"https://www.ostechnix.com/an-easy-way-to-remove-programs-installed-from-source-in-linux/"},{default:l(()=>[...s[0]||(s[0]=[e("https://www.ostechnix.com/an-easy-way-to-remove-programs-installed-from-source-in-linux/",-1)])]),_:1})]),t("p",null,[s[6]||(s[6]=e("作者：",-1)),a(i,{href:"https://www.ostechnix.com/author/sk/"},{default:l(()=>[...s[2]||(s[2]=[e("SK",-1)])]),_:1}),s[7]||(s[7]=e(" 選題：",-1)),a(i,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[3]||(s[3]=[e("lujun9972",-1)])]),_:1}),s[8]||(s[8]=e(" 譯者：",-1)),a(i,{href:"https://github.com/dianbanjiu"},{default:l(()=>[...s[4]||(s[4]=[e("dianbanjiu",-1)])]),_:1}),s[9]||(s[9]=e(" 校對：",-1)),a(i,{href:"https://github.com/wxy"},{default:l(()=>[...s[5]||(s[5]=[e("wxy",-1)])]),_:1})]),t("p",null,[s[12]||(s[12]=e("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[10]||(s[10]=[e("LCTT",-1)])]),_:1}),s[13]||(s[13]=e(" 原創編譯，",-1)),a(i,{href:"https://linux.cn/"},{default:l(()=>[...s[11]||(s[11]=[e("Linux中國",-1)])]),_:1}),s[14]||(s[14]=e(" 榮譽推出",-1))])])}const x=o(r,[["render",c]]);export{w as __pageData,x as default};
